const clean = v => typeof v === 'string' ? v.trim() : '';
const priorities = ['CRÍTICA','ALTA','MÉDIA','BAIXA'];
function validData(d) {
  return !!d && typeof d === 'object' &&
    ['nome_completo','matricula_id','email','descricao_problema','prioridade_interna'].every(k => typeof d[k] === 'string' && d[k].trim().length > 0) &&
    /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email) && priorities.includes(d.prioridade_interna);
}
function codeFor(value) {
  let h = 2166136261;
  for (let i = 0; i < value.length; i++) h = Math.imul(h ^ value.charCodeAt(i), 16777619);
  return (h >>> 0).toString(36).toUpperCase().padStart(7,'0');
}

const base = $('Dados').item.json;
if (![base.session,base.chatId,base.payload_id].every(v => clean(v))) throw new Error('Mensagem sem sessão, remetente ou identificador.');
const stateKey = 'ti:cadastro:v1:' + encodeURIComponent(base.session) + ':' + encodeURIComponent(base.chatId);
let state = null;
try { state = typeof $json.estado_atendimento === 'string' ? JSON.parse($json.estado_atendimento) : $json.estado_atendimento; } catch {}
const fresh = state && typeof state === 'object' && Number(state.expira_em) > Date.now() &&
  state.session === base.session && state.chatId === base.chatId;
if (!fresh) state = null;
const cmd = clean(base.message).replace(/[.!]$/,'').toUpperCase();
const confirmation = state && ['aguardando_confirmacao','registrado'].includes(state.etapa) &&
  cmd === 'CONFIRMAR ' + state.codigo && validData(state.dados);
const data = confirmation ? state.dados : state && state.etapa !== 'registrado' ? state.dados || {} : {};
const stableId = confirmation ? state.atendimento_id :
  'waha:' + base.session + ':' + base.chatId + ':' + base.payload_id;
const result = {
  ...base, state_key: stateKey, estado_anterior: state,
  dados_atuais: data, atendimento_id: stableId,
  gravar: Boolean(confirmation),
  chamado: confirmation ? {atendimento_id: stableId, ...data, status:'PENDENTE'} : null
};
return [{json:result, pairedItem:{item:0}}];

