const turn = $('Preparar atendimento').item.json;
const expires = Date.now() + 3000000;
const stateBase = {session:turn.session,chatId:turn.chatId,expira_em:expires};
let parsed = null;
try {
  const raw = typeof $json.output === 'string' ? $json.output.trim().replace(/^\x60\x60\x60(?:json)?\s*/i,'').replace(/\s*\x60\x60\x60$/,'') : $json.output;
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch {}
let data = {};
for (const k of ['nome_completo','matricula_id','email','descricao_problema','prioridade_interna']) {
  data[k] = clean(turn.dados_atuais?.[k]);
}
let reply = 'Não consegui processar essa mensagem agora. Pode tentar novamente?';
let state = {...stateBase, etapa:'coletando', dados:data};
if (parsed && typeof parsed === 'object' && !Array.isArray(parsed) && parsed.dados && typeof parsed.dados === 'object') {
  for (const k of Object.keys(data)) {
    if (typeof parsed.dados[k] === 'string') data[k] = clean(parsed.dados[k]);
  }
  data.email = data.email.toLowerCase();
  data.prioridade_interna = data.prioridade_interna.toUpperCase();
  if (data.prioridade_interna === 'CRITICA') data.prioridade_interna='CRÍTICA';
  if (data.prioridade_interna === 'MEDIA') data.prioridade_interna='MÉDIA';
  state.dados=data;
  if (validData(data)) {
    const codigo = codeFor(turn.atendimento_id + ':' + JSON.stringify(data));
    state = {...stateBase, etapa:'aguardando_confirmacao', atendimento_id:turn.atendimento_id, codigo, dados:data};
    reply = 'Confira os dados do chamado:\n\nNome: ' + data.nome_completo +
      '\nMatrícula/ID: ' + data.matricula_id + '\nE-mail: ' + data.email +
      '\nProblema: ' + data.descricao_problema +
      '\n\nSe estiver tudo correto, responda CONFIRMAR ' + codigo +
      '. Se precisar ajustar algo, envie a correção.';
  } else {
    const missing = [
      ['nome_completo','seu nome completo'],['matricula_id','sua matrícula ou ID'],
      ['email','um e-mail válido'],['descricao_problema','uma descrição do problema']
    ].find(([k]) => !clean(data[k]) || (k==='email' && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(data[k])));
    const candidate = clean(parsed.resposta_cliente);
    reply = missing ? 'Para continuar, informe ' + missing[1] + ', por favor.' :
      'Preciso entender melhor o problema. Pode explicar o que acontece?';
    if (missing && candidate && !/prioridade|CRÍTICA|MÉDIA|registrad[oa]|protocolo/i.test(candidate) &&
        !candidate.includes('{') && candidate.length <= 1200) reply=candidate;
  }
}
return [{json:{state_key:turn.state_key, estado_salvar:state, resposta_cliente:reply},pairedItem:{item:0}}];

